function readOauthStateStore(){try{return JSON.parse(fs.readFileSync(OAUTH_STATE_FILE,'utf8'))||{}}catch{return {}}}
function saveOauthStateStore(v){atomicJsonWrite(OAUTH_STATE_FILE,v)}
function safeReturnTo(v){const raw=String(v||'/?open=integraties');if(!raw.startsWith('/')||raw.startsWith('//'))return '/?open=integraties';return raw}
function issueOAuthState(provider,c,returnTo){const states=readOauthStateStore(),now=Date.now();for(const [k,v] of Object.entries(states))if(!v||Number(v.expires_at||0)<now)delete states[k];const token=crypto.randomBytes(32).toString('base64url');states[token]={provider,tenant_id:c.tenant_id,dealer_id:c.dealer_id,return_to:safeReturnTo(returnTo),issued_at:now,expires_at:now+15*60*1000};saveOauthStateStore(states);return token}
function consumeOAuthState(provider,token){const states=readOauthStateStore(),key=String(token||''),st=states[key];if(!st)throw new Error('OAuth state ongeldig, verlopen of al gebruikt');delete states[key];saveOauthStateStore(states);if(st.provider!==provider)throw new Error('OAuth state provider mismatch');if(Number(st.expires_at||0)<Date.now())throw new Error('OAuth state verlopen');return st}
async function googleAccess(c){ const g=googleConfig(), saved=loadGoogle(c); if(!saved?.refresh_token&&!saved?.access_token) throw new Error('Google is niet gekoppeld'); if(saved.access_token&&Number(saved.expires_at||0)>Date.now()+60000)return saved.access_token; if(!saved.refresh_token)throw new Error('Google refresh token ontbreekt'); const r=await fetch('https://oauth2.googleapis.com/token',{method:'POST',headers:{'content-type':'application/x-www-form-urlencoded'},body:new URLSearchParams({client_id:g.client_id,client_secret:g.client_secret,refresh_token:saved.refresh_token,grant_type:'refresh_token'})}); const j=await r.json(); if(!r.ok)throw new Error(`Google token refresh ${r.status}: ${j.error_description||j.error||'mislukt'}`); const next={...saved,...j,refresh_token:saved.refresh_token,expires_at:Date.now()+Number(j.expires_in||3600)*1000}; saveGoogle(c,next); return next.access_token; }
