async function openaiWebSearch(query,c){ const apiKey=cleanEnv('OPENAI_API_KEY')||cleanEnv('FOUNDLY_AI_API_KEY'); if(!apiKey)throw new Error('OPENAI_API_KEY ontbreekt'); const model=cleanEnv('FOUNDLY_SEARCH_MODEL')||cleanEnv('FOUNDLY_AI_MODEL')||'gpt-5.6'; const input=`Je bent Foundly Search Intelligence voor de Nederlandse automotive markt. Zoek actueel op het web en geef feitelijke, brongebonden informatie. Verzin geen zoekvolumes of marktdata. Vraag: ${query}`; const r=await fetch('https://api.openai.com/v1/responses',{method:'POST',headers:{'content-type':'application/json','authorization':`Bearer ${apiKey}`},body:JSON.stringify({model,input,tools:[{type:'web_search'}]})}); const j=await r.json(); if(!r.ok)throw new Error(`OpenAI web search ${r.status}: ${j.error?.message||'mislukt'}`); const text=j.output_text||((j.output||[]).flatMap(x=>x.content||[]).find(x=>x.type==='output_text')||{}).text||''; const sources=[]; for(const item of j.output||[]){ if(item.type==='web_search_call'&&item.action?.sources)for(const src of item.action.sources)sources.push(src); for(const part of item.content||[])for(const a of part.annotations||[])if(a.type==='url_citation')sources.push({type:'url',url:a.url,title:a.title}); }
  const rec={id:id(),at:new Date().toISOString(),query,text,sources:[...new Map(sources.filter(x=>x?.url).map(x=>[x.url,x])).values()]}; arr(records,key(c,'data')).push({_source:'openai_web_search',...rec}); return rec; }


