const connectorCache = new Map();
function cleanEnv(name, fallback=''){
  const raw=process.env[name];
  if(raw===undefined||raw===null)return fallback;
  let v=String(raw).trim();
  if((v.startsWith('\"')&&v.endsWith('\"'))||(v.startsWith("'")&&v.endsWith("'")))v=v.slice(1,-1).trim();
  return v;
}
function splitScopes(raw, fallback=[]){
  const v=String(raw||'').trim();
  return (v?v.split(/[\s,]+/):fallback).map(x=>String(x).trim()).filter(Boolean);
}
function metaScopes(){
  // Deliberately safe default for the Marketing API/Facebook Login for Business use case.
  // Instagram-specific permissions can be added later via META_EXTRA_SCOPES after the app has access to them.
  const safe=['public_profile','ads_read','ads_management','business_management','pages_show_list','pages_read_engagement'];
  const requested=splitScopes(cleanEnv('META_SCOPES'), safe);
  const extras=splitScopes(cleanEnv('META_EXTRA_SCOPES'), []);
  const blocked=new Set(['email','instagram_basic','instagram_manage_insights','leads_retrieval']);
  const allowBlocked=cleanEnv('META_ALLOW_UNREVIEWED_SCOPES','false').toLowerCase()==='true';
  return [...new Set([...requested,...extras].filter(x=>allowBlocked||!blocked.has(x)))];
}
function secretFingerprint(v){
  const s=String(v||'');
  return s?crypto.createHash('sha256').update(s).digest('hex').slice(0,10):null;
}
