async function probeMeta(c,force=false){const ck=key(c,'connector-meta'),cached=connectorCache.get(ck);if(!force&&cached&&Date.now()-cached.at<60000)return cached.value;const saved=loadConnector(c,'meta');const configured=OAUTH_PROVIDERS.meta.configured();const base={id:'meta',configured,token_stored:Boolean(saved?.access_token),connected:false,services:{meta:false,instagram:false},account:null,ad_accounts:0,pages:0,error:null};if(!configured||!saved?.access_token){connectorCache.set(ck,{at:Date.now(),value:base});return base;}try{const v=metaVersion();const me=await jfetch(`https://graph.facebook.com/${v}/me?fields=id,name&access_token=${encodeURIComponent(saved.access_token)}`);base.account=me;base.services.meta=true;const [ads,pages]=await Promise.allSettled([jfetch(`https://graph.facebook.com/${v}/me/adaccounts?fields=id,name,account_status,currency&limit=50&access_token=${encodeURIComponent(saved.access_token)}`),jfetch(`https://graph.facebook.com/${v}/me/accounts?fields=id,name,instagram_business_account&limit=100&access_token=${encodeURIComponent(saved.access_token)}`)]);if(ads.status==='fulfilled')base.ad_accounts=(ads.value.data||[]).length;if(pages.status==='fulfilled'){base.pages=(pages.value.data||[]).length;base.services.instagram=(pages.value.data||[]).some(x=>x.instagram_business_account?.id);}base.connected=true;}catch(e){base.error=e.message;}connectorCache.set(ck,{at:Date.now(),value:base});return base;}
