const server=http.createServer(async(req,res)=>{const u=new URL(req.url,`http://${req.headers.host||'localhost'}`);try{if(u.pathname.startsWith('/api/')){const handled=await api(req,res,u);if(handled!==false)return;}if(u.pathname==='/'||u.pathname==='/index.html'){if(!fs.existsSync(INDEX)){res.writeHead(500);return res.end('index.html ontbreekt');}res.writeHead(200,{'content-type':'text/html; charset=utf-8'});return fs.createReadStream(INDEX).pipe(res);}res.writeHead(404);res.end('Not found');}catch(err){console.error(err);json(res,500,{error:err.message});}});
server.listen(PORT,'0.0.0.0',()=>{console.log(`Foundly OS v4.1.0 ONLINE op poort ${PORT}`);if(!(DATA==='/data'||DATA.startsWith('/data/')))console.warn('[PERSISTENCE WARNING] FOUNDLY_DATA_DIR staat niet op /data; koppel een Railway Volume voor duurzame OAuth tokens en databases.');const c={tenant_id:'default',dealer_id:'default'};addEvent(c,'system','Foundly OS v4.1.0 gestart',{port:PORT,persistence:true,data_dir:DATA});});
const workerMs=Math.max(60000,Number(cleanEnv('FOUNDLY_WORKER_INTERVAL_MS','300000'))||300000);setInterval(()=>workerTick({tenant_id:'default',dealer_id:'default'}).catch(e=>console.error('[WORKER ERROR]',e.message)),workerMs).unref();

